import React from 'react';

interface IStepContext {
  error: boolean;
  completed: boolean;
  active: boolean;
  disabled: boolean;
  index: number;
}

const StepContext = React.createContext<IStepContext>({
  error: false,
  completed: false,
  active: false,
  disabled: false,
  index: 0,
});

export default StepContext;
